using System;
using System.Collections.Generic;
using System.Linq;

public record InternalTx(string TxId, decimal Amount, string Status);
public record BankSettlementTx(string TxId, decimal Amount);

public class ReconciliationEngine
{
    public static (int matched, int missingInBank, int missingInInternal) Reconcile(
        List<InternalTx> internalRecords, 
        List<BankSettlementTx> bankRecords)
    {
        var bankMap = bankRecords.ToDictionary(b => b.TxId, b => b.Amount);
        var internalMap = internalRecords.ToDictionary(i => i.TxId, i => i.Amount);

        int matched = 0;
        int missingInBank = 0;

        foreach (var itx in internalRecords)
        {
            if (bankMap.TryGetValue(itx.TxId, out decimal bankAmount) && bankAmount == itx.Amount)
            {
                matched++;
            }
            else
            {
                missingInBank++;
            }
        }

        int missingInInternal = bankRecords.Count(b => !internalMap.ContainsKey(b.TxId));

        return (matched, missingInBank, missingInInternal);
    }
}

public class Program
{
    public static void Main()
    {
        var internalTxs = new List<InternalTx>
        {
            new("TX_001", 100_000m, "SETTLED"),
            new("TX_002", 250_000m, "SETTLED"),
            new("TX_003", 500_000m, "SETTLED")
        };

        var bankTxs = new List<BankSettlementTx>
        {
            new("TX_001", 100_000m),
            new("TX_002", 250_000m),
            new("TX_004", 75_000m)
        };

        var (matched, missingBank, missingInternal) = ReconciliationEngine.Reconcile(internalTxs, bankTxs);

        Console.WriteLine($"[Hasil Rekonsiliasi]");
        Console.WriteLine($"Matched Transaksi       : {matched} (Ekspektasi: 2)");
        Console.WriteLine($"Missing in Bank Report  : {missingBank} (Ekspektasi: 1)");
        Console.WriteLine($"Missing in Internal DB  : {missingInternal} (Ekspektasi: 1)");
    }
}
